#include "space_invaders/game.h"
#include <assert.h>
int main(void) { Game g, same; game_init_seed(&g, 42); game_init_seed(&same, 42); assert(g.seed == same.seed && g.player == 22 && g.lives == 3 && g.room == 1); g.score = 4; g.alien = g.player; g.bullet = g.alien_row; game_step(&g); assert(g.score == 5 && g.upgrade_offer && g.paused); game_choose_upgrade(&g, 2); assert(!g.upgrade_offer && !g.paused && g.lives == 4); assert(game_shield_hit(&g, 1, SHIELD_ROW)); g.bonus_active = true; g.bonus_x = g.player; g.bullet = 1; game_step(&g); assert(g.score > 5 && !g.bonus_active); g.over = true; game_restart(&g); assert(!g.over && !g.paused && g.lives == 3 && g.room == 1); return 0; }
